import {accessStatus,requestAccess,decideAccess,validatePass} from './access.mjs';
import {SMART_LOCK_API,smartLockUrl} from './smart-locks.mjs';
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=value=>new Date(value).toLocaleString('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
const labels={profile:'Заполните локальный профиль',unpaid:'Демобронь ещё не оплачена',new:'Демопрофиль ещё не отправлен',changed:'Профиль изменён',pending:'Демозаявка ожидает подтверждения',rejected:'Демозаявка отклонена',revoked:'Демодоступ отозван',ready:'Демопрофиль подтверждён',active:'Демопрофиль подтверждён',expired:'Срок демоброни завершён',missing:'Бронь не найдена'};
export function createAccessUI({db,save,showModal,toast,navigate,refresh}){
 const find=id=>db().bookings.find(b=>b.id===id),state=b=>accessStatus(b,db().profile);
 function physicalLink(b){try{return '<a class="button primary" href="'+smartLockUrl(b.snapshot?.lockDeviceId)+'">Проверить серверную бронь</a>'}catch{return '<a class="button primary" href="#locks">Как войти по QR устройства</a>'}}
 function card(b){return '<div class="booking-access"><p class="access-status">Для физического входа отсканируйте QR с экрана ESP32.</p>'+physicalLink(b)+'</div>'}
 function ownerPanel(){const bookings=db().bookings.filter(b=>b.accessRequest);return '<section class="access-owner-panel"><div class="access-section-head"><h2>Демозаявки каталога</h2><a class="button" href="'+SMART_LOCK_API+'/owner">Устройства и серверные брони</a></div><p class="mini-note">Эти локальные заявки не управляют замками. Физический доступ выдаётся только по серверной брони.</p>'+bookings.map(b=>'<article class="access-request"><div><h3>'+escape(b.accessRequest.profile.name)+'</h3><p>'+escape(b.snapshot.title)+' · '+date(b.start)+' — '+date(b.end)+'</p><p>'+escape(labels[state(b)])+'</p></div><button class="button" data-action="access-review" data-id="'+escape(b.id)+'">Демозаявка</button></article>').join('')+'</section>'}
 function open(id){const b=find(id);if(!b)return toast('Бронь не найдена');const s=state(b);showModal('Вход по QR устройства','<div class="dialog-content"><h3>'+escape(b.snapshot.title)+'</h3><p>На ESP32‑2432S028R отображается QR с публичной ссылкой устройства. После сканирования войдите в аккаунт и запросите открытие по серверной брони.</p>'+physicalLink(b)+'<p class="test-note">Демобронь этого каталога не разрешает импульс реле. Секрет устройства и постоянный токен открытия в QR не передаются.</p><div class="dialog-actions">'+(['new','changed','rejected','revoked'].includes(s)?'<button class="button" data-action="access-request" data-id="'+escape(id)+'">Отправить демопрофиль владельцу</button>':'')+'</div></div>',true)}
 function review(id){const b=find(id);if(!b?.accessRequest)return toast('Заявка не найдена');const s=state(b),p=b.accessRequest.profile;showModal('Демозаявка каталога','<div class="dialog-content"><h3>'+escape(p.name)+'</h3><p>'+escape(p.email)+'</p><p>'+escape(labels[s])+'</p><p class="test-note">Действие влияет только на локальную демобронь. QR и команды физическому замку не выдаются.</p><div class="dialog-actions">'+(s==='pending'?'<button class="button" data-action="access-reject" data-id="'+escape(id)+'">Отклонить</button><button class="button" data-action="access-approve" data-id="'+escape(id)+'">Подтвердить демопрофиль</button>':['ready','active'].includes(s)?'<button class="button danger" data-action="access-revoke" data-id="'+escape(id)+'">Отозвать демодоступ</button>':'')+'</div></div>',true)}
 function read(id,token){showModal('Старая демоссылка','<div class="dialog-content"><p>'+escape(validatePass(find(id),db().profile,token).reason)+'</p><a class="button primary" href="#locks">Доступ по QR устройства</a></div>',true)}
 function handle(action,id){if(!action.startsWith('access-'))return false;const b=find(id);switch(action){case'access-owner':navigate('owner');break;case'access-open':open(id);break;case'access-request':requestAccess(b,db().profile);save();refresh();open(id);toast('Демозаявка сохранена на этом устройстве');break;case'access-review':review(id);break;case'access-approve':case'access-reject':case'access-revoke':decideAccess(b,db().profile,{'access-approve':'approved','access-reject':'rejected','access-revoke':'revoked'}[action],null);save();refresh();review(id);break;case'access-check':read(id,null);break;}return true}
 return {card,ownerPanel,open,read,handle};
}
